// Block (composition) — promo-code entry with a consumer-controlled applied state.
import type { FormEvent } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./CouponInput.css";

export interface CouponInputProps {
  onApply?: (code: string) => void;
  onRemove?: () => void;
  appliedCode?: string;
  label?: string;
}

export function CouponInput({
  onApply,
  onRemove,
  appliedCode,
  label = "Promo code",
}: CouponInputProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const code = String(new FormData(event.currentTarget).get("code") ?? "").trim();
    if (code) onApply?.(code);
  };

  return (
    <div className="sd-couponinput">
      {appliedCode ? (
        <Stack direction="row" align="center" justify="between" gap="small" className="sd-couponinput__applied">
          <Badge variant="neutral">{appliedCode}</Badge>
          <Separator orientation="vertical" />
          {/* usage: item-action — it removes the one applied code shown beside it */}
          <Button type="button" variant="secondary" size="small" onPress={onRemove}>
            Remove
          </Button>
        </Stack>
      ) : (
        <Form onSubmit={handleSubmit}>
          <Stack
            direction={{ small: "column", medium: "row" }}
            align={{ small: "stretch", medium: "end" }}
            gap="small"
            className="sd-couponinput__form"
          >
            <TextField
              name="code"
              label={label}
              autoComplete="off"
              isRequired
              className="sd-couponinput__field"
            />
            <Button type="submit" className="sd-couponinput__action">
              Apply
            </Button>
          </Stack>
        </Form>
      )}
    </div>
  );
}

/* CouponInput.css — arrangement only; composed Components own their look. */
.sd-couponinput {
  width: 100%;
}

.sd-couponinput__field {
  flex: 1;
  min-width: 0;
}

.sd-couponinput__action {
  flex: none;
}
